"""గణితం – అధ్యాయాలు 2, 3, 6, 7, 10–14 ప్రశ్నలకు గ్రాఫ్‌లు, పటాలు, పట్టికలు (figs_mat.py లో FIG కి కలుస్తాయి)"""
import os, sys, math
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..'))
from figlib import F, P, S, L, FN, PG, C, A, R, M, T, ang, ARC, EL, SECTOR, line_lbl

FILL = '#eff6ff'
def pol(r, d): return (round(r * math.cos(math.radians(d)), 3), round(r * math.sin(math.radians(d)), 3))

# ── 2. బహుపదులు: గ్రాఫ్‌లు ──
def parab(ex, zeros, v, w=260, cap=None, extra=()):
    return F(v, FN(ex, '', None, None, None, None, '1'), *[P(z, 0, str(z).replace('-', '−'), 'nw' if i == 0 and len(zeros) > 1 else 'ne', '2') for i, z in enumerate(zeros)], *extra,
             g=1, st=1, n=1, w=w, cap=cap)

# ── 3. రేఖీయ సమీకరణాలు: జవాబు గ్రాఫ్‌లు ──
def lines2(eqs, sol, v, st=1, n=1, w=280, cap=None, pts=(), extra=()):
    e = []
    W = v[1] - v[0]; Hh = v[3] - v[2]
    for i, (a, b, c, lb) in enumerate(eqs):
        e.append(L(a, b, c, '', None, None, str(i + 1)))
        best = None
        for fr in ([0.62, 0.72, 0.52, 0.82, 0.42] if i == 0 else [0.18, 0.28, 0.1, 0.36, 0.45]):
            if abs(b) < 1e-9: x, y = -c / a, v[2] + Hh * fr
            else:
                x = v[0] + W * fr; y = (-c - a * x) / b
            if v[2] + Hh * 0.1 < y < v[3] - Hh * 0.1 and x + W * 0.38 < v[1] + W * 0.02: best = (x, y); break
            if v[2] + Hh * 0.1 < y < v[3] - Hh * 0.1 and best is None: best = (x, y)
        if best is None: best = (v[0] + W * 0.3, v[3] - Hh * 0.15)
        right = best[0] + W * 0.36 < v[1]
        e.append(T(round(best[0] + (W * 0.03 if right else -W * 0.03), 2), round(best[1] + Hh * 0.02, 2), lb, 'start' if right else 'end', 11, str(i + 1), 1))
    for (x, y) in pts: e.append(P(x, y, '', 'ne', '5'))
    e += list(extra)
    e.append(P(sol[0], sol[1], f'({sol[0]}, {sol[1]})'.replace('-', '−'), 'e'))
    return F(v, *e, g=1, st=st, n=n, w=w, cap=cap or f'రేఖలు ({sol[0]}, {sol[1]}) వద్ద ఖండించుకుంటాయి → x = {sol[0]}, y = {sol[1]}'.replace('-', '−'))

# ── 6. త్రిభుజాలు ──
BA, BB, BC_ = (3, 4.5), (0, 0), (6.5, 0)
def bpt(t, labs=(), cap='DE ∥ BC', extra=(), w=260):
    """ΔABC లో AD/AB = t వద్ద DE ∥ BC; labs = (AD, DB, AE, EC)"""
    D = (BA[0] + (BB[0] - BA[0]) * t, BA[1] + (BB[1] - BA[1]) * t); E = (BA[0] + (BC_[0] - BA[0]) * t, BA[1] + (BC_[1] - BA[1]) * t)
    l = list(labs) + [''] * 4
    return F([-1.6, 8.2, -1.0, 5.3], PG([BA, BB, BC_], FILL), S(*D, *E, 'b1'), P(*BA, 'A', 'n'), P(*BB, 'B', 'sw'), P(*BC_, 'C', 'se'), P(*D, 'D', 'w'), P(*E, 'E', 'e'),
             M(*BA, *D, l[0], 1) if l[0] else None, M(*D, *BB, l[1], 1) if l[1] else None, M(*BA, *E, l[2], -1) if l[2] else None, M(*E, *BC_, l[3], -1) if l[3] else None,
             *extra, w=w, cap=cap)

def tri_pts(*pts, fill=FILL): return PG([list(p) for p in pts], fill)

# ── 7. నిరూపక జ్యామితి ──
def grid_poly(pts, names, v, w=270, cap=None, closed=True, n=1, extra=()):
    e = [PG([list(p) for p in pts], '#dbeafe66', '#2563eb')] if closed else []
    for p, nm in zip(pts, names): e.append(P(p[0], p[1], f'{nm}({p[0]}, {p[1]})'.replace('-', '−'), 'ne'))
    return F(v, *e, *extra, g=1, st=1, n=n, w=w, cap=cap)

# ── 10. వృత్తాలు ──
def two_tangents(r=2, d=5, tlab='P', labs=('', '', ''), cap=None, w=260, angle=None):
    a = math.degrees(math.acos(r / d)); A1, B1 = pol(r, a), pol(r, -a)
    return F([-r - 0.8, d + 1.0, -r - 0.8, r + 0.8], C(0, 0, r), S(0, 0, d, 0, 'd'), S(d, 0, *A1, '1'), S(d, 0, *B1, '1'), S(0, 0, *A1), S(0, 0, *B1),
             R(*A1, ang(*A1, 0, 0), ang(*A1, d, 0), 0.25), R(*B1, ang(*B1, 0, 0), ang(*B1, d, 0), 0.25), P(0, 0, 'O', 's'), P(d, 0, tlab, 'e'),
             P(*A1, 'A', 'n'), P(*B1, 'B', 's'), M(0, 0, *A1, labs[0], -1) if labs[0] else None, M(0, 0, d, 0, labs[1], 1) if labs[1] else None,
             M(d, 0, *A1, labs[2], 1) if labs[2] else None, angle, w=w, cap=cap)

def tangential_quad(phis, names='ABCD', tnames='PQRS', r=2, cap=None, w=250):
    vs = []
    for i in range(4):
        p1, p2 = phis[i], phis[(i + 1) % 4]; dlt = (p2 - p1) % 360; m = p1 + dlt / 2
        vs.append(pol(r / math.cos(math.radians(dlt / 2)), m))
    e = [PG([list(v) for v in vs], FILL), C(0, 0, r), P(0, 0, 'O', 's')]
    for i, v in enumerate(vs): e.append(P(*v, names[i], 'ne' if v[0] >= 0 and v[1] >= 0 else 'nw' if v[1] >= 0 else 'sw' if v[0] < 0 else 'se'))
    for i, p in enumerate(phis): e.append(P(*pol(r, p), tnames[i], 'ne', '2'))
    xs = [v[0] for v in vs]; ys = [v[1] for v in vs]
    return F([min(xs) - 1, max(xs) + 1, min(ys) - 1, max(ys) + 1], *e, w=w, cap=cap)

# ── 12. ఘనాకృతులు (3D) ──
def solid_hemi(r=3, lab='r = 7 సెం.మీ.'):
    return F([-r - 0.8, r + 0.8, -r - 0.6, 1.4], *EL(0, 0, r, r * 0.3), ARC(0, 0, r, r, 180, 360), S(0, 0, r, 0, 'd'), P(0, 0, '', 'n'), T(r / 2, 0.25, lab, 'middle', 11), w=220)
def capsule(L_=4.5, r=1.25, labs=('', ''), cap=None, w=280):
    h = L_ / 2
    return F([-h - r - 0.6, h + r + 1.8, -r - 1.1, r + 1.0], S(-h, r, h, r), S(-h, -r, h, -r), ARC(-h, 0, r, r, 90, 270), ARC(h, 0, r, r, -90, 90),
             *EL(-h, 0, r * 0.3, r, 'd'), *EL(h, 0, r * 0.3, r, 'd'), S(-h - r, -r - 0.55, h + r, -r - 0.55, 'A'), T(0, -r - 0.95, labs[0], 'middle', 11),
             S(h + r + 0.25, -r, h + r + 0.25, r, 'A'), T(h + r + 0.4, 0, labs[1], 'start', 11), w=w, cap=cap)
def cone_on_hemi(r=2, hc=2, labs=('', '', ''), cap=None, w=240):
    return F([-r - 1.6, r + 1.6, -r - 0.5, hc + 0.7], *EL(0, 0, r, r * 0.3, '', True), ARC(0, 0, r, r, 180, 360), S(-r, 0, 0, hc), S(r, 0, 0, hc),
             S(0, 0, 0, hc, 'd'), S(0, 0, r, 0, 'd'), T(r / 2, 0.15, labs[0], 'middle', 11), T(0.15, hc / 2, labs[1], 'start', 11),
             M(r, 0, 0, hc, labs[2], 1) if labs[2] else None, w=w, cap=cap)

def tbl(*rows): return '\n'.join(' | '.join(str(c) for c in r) for r in rows)

